export function illuminate(THREE, scene) {
  const key = new THREE.DirectionalLight(0xfff1df, 2);
  key.position.set(-3, 4, 5);

  const fill = new THREE.DirectionalLight(0xe4eeff, 0.6);
  fill.position.set(4, 2, 3);

  scene.add(key, fill, key.target, fill.target);
}
```

